        ["pub.object.needid"] = new() { ["en"] = "Enter the profile's id and your proof reference.", ["es"] = "Introduzca el id del perfil y su referencia de prueba.", ["fr"] = "Saisissez l'identifiant du profil et votre référence de preuve.", ["de"] = "Geben Sie die Profil-ID und Ihre Nachweisreferenz ein.", ["pt"] = "Introduza o id do perfil e a sua referência de prova.", ["it"] = "Inserisci l'id del profilo e il tuo riferimento di prova.", ["ja"] = "プロフィールIDと証明の参照番号を入力してください。", ["zh"] = "请输入资料 id 和你的证明参考号。", ["hi"] = "प्रोफ़ाइल आईडी और अपना प्रमाण संदर्भ दर्ज करें।", ["ar"] = "أدخل معرّف الملف ومرجع إثباتك." },
        ["pub.mark.needtext"] = new() { ["en"] = "Paste the text first.", ["es"] = "Pegue primero el texto.", ["fr"] = "Collez d'abord le texte.", ["de"] = "Fügen Sie zuerst den Text ein.", ["pt"] = "Cole primeiro o texto.", ["it"] = "Incolla prima il testo.", ["ja"] = "先にテキストを貼り付けてください。", ["zh"] = "请先粘贴文本。", ["hi"] = "पहले पाठ चिपकाएँ।", ["ar"] = "الصق النص أولاً." },
        ["pub.object.ref.ph"] = new() { ["en"] = "an identity check held elsewhere", ["es"] = "una verificación de identidad hecha en otro sitio", ["fr"] = "une vérification d'identité conservée ailleurs", ["de"] = "eine anderswo geführte Identitätsprüfung", ["pt"] = "uma verificação de identidade guardada noutro lado", ["it"] = "una verifica d'identità conservata altrove", ["ja"] = "他所で行われた本人確認", ["zh"] = "在别处完成的身份验证", ["hi"] = "कहीं और रखी गई पहचान जाँच", ["ar"] = "تحقّق من الهوية محفوظ في مكان آخر" },
        ["tab.people"] = new() { ["en"] = "People", ["es"] = "Personas", ["fr"] = "Personnes", ["de"] = "Leute", ["pt"] = "Pessoas", ["it"] = "Persone", ["ja"] = "人", ["zh"] = "人脉", ["hi"] = "लोग", ["ar"] = "الأشخاص" },
